script.setup:
// MediaPipe is fetched on demand from the CDN (nothing bundled), with its model from Google's storage.
const { FilesetResolver, HandLandmarker } = await ctx.utils.import("https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@1.0.1/vision_bundle.mjs");
const fileset = await FilesetResolver.forVisionTasks("https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@1.0.1/wasm");
ctx.state.hands = await HandLandmarker.createFromOptions(fileset, {
  baseOptions: { modelAssetPath: "https://storage.googleapis.com/mediapipe-models/hand_landmarker/hand_landmarker/float16/1/hand_landmarker.task", delegate: "GPU" },
  runningMode: "VIDEO",
  numHands: 2,
});
ctx.state.cam = await ctx.utils.createCameraTexture({ width: 640, height: 480 });
ctx.state.points = new Float32Array(84);
ctx.state.count = 0;
ctx.state.p = ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER, "#version 300 es
precision highp float;
in vec2 v_uv;
out vec4 outColor;
uniform sampler2D u_cam;
uniform vec2 u_resolution;
uniform vec2 u_points[42];
uniform int u_count;
uniform float u_dim;
uniform float u_size;
uniform vec3 u_color;
void main() {
  // Mirrored, like looking in a mirror.
  vec3 cam = texture(u_cam, vec2(1.0 - v_uv.x, v_uv.y)).rgb * u_dim;
  vec2 aspect = vec2(u_resolution.x / u_resolution.y, 1.0);
  float glow = 0.0;
  for (int i = 0; i < 42; i++) {
    if (i >= u_count) break;
    float d = length((v_uv - u_points[i]) * aspect);
    glow += u_size * 0.0004 / (d * d + 0.0001);
  }
  outColor = vec4(cam + u_color * min(glow, 3.0), 1.0);
}");

script.render:
const s = ctx.state;
s.cam.update();
const video = s.cam.video;
// Detect once per new camera frame.
if (video.readyState >= 2 && video.currentTime !== s.lastTime) {
  s.lastTime = video.currentTime;
  const result = s.hands.detectForVideo(video, performance.now());
  const points = result.landmarks.flat().slice(0, 42);
  points.forEach((p, i) => { s.points[i * 2] = 1 - p.x; s.points[i * 2 + 1] = 1 - p.y; });
  s.count = points.length;
  ctx.publish("hands", result.landmarks.length);
}
ctx.gl.useProgram(s.p);
ctx.utils.bindTexture(s.p, "u_cam", s.cam.texture, 0);
ctx.utils.drawFullscreen(s.p, { u_points: s.points, u_count: s.count });
